CREATE TABLE projects (id VARCHAR PRIMARY KEY, name VARCHAR NOT NULL);
CREATE TABLE runs (id VARCHAR PRIMARY KEY, project_id VARCHAR NOT NULL REFERENCES projects(id), state VARCHAR NOT NULL, version INTEGER NOT NULL CHECK (version > 0));
CREATE TABLE approvals (id VARCHAR PRIMARY KEY, project_id VARCHAR NOT NULL REFERENCES projects(id), actor_id VARCHAR NOT NULL, payload TEXT NOT NULL, revoked INTEGER NOT NULL CHECK (revoked IN (0, 1)));
CREATE TABLE events (id VARCHAR PRIMARY KEY, project_id VARCHAR NOT NULL REFERENCES projects(id), sequence INTEGER NOT NULL, payload TEXT NOT NULL, previous_hash VARCHAR NOT NULL, hash VARCHAR NOT NULL, UNIQUE(project_id, sequence));
CREATE TABLE commands (id VARCHAR PRIMARY KEY, request_hash VARCHAR NOT NULL, result TEXT NOT NULL);
CREATE TABLE outbox (id VARCHAR PRIMARY KEY, event_id VARCHAR NOT NULL REFERENCES events(id), state VARCHAR NOT NULL);
